import{_ as n,o as e,c as o,a3 as t,j as s}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"02 · TCP 连接管理：三次握手、四次挥手、TIME_WAIT","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/02.md","filePath":"bagu/network/02.md"}'),l={name:"bagu/network/02.md"};function p(r,a,i,c,d,u){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_02-·-tcp-连接管理-三次握手、四次挥手、time-wait" tabindex="-1">02 · TCP 连接管理：三次握手、四次挥手、TIME_WAIT <a class="header-anchor" href="#_02-·-tcp-连接管理-三次握手、四次挥手、time-wait" aria-label="Permalink to &quot;02 · TCP 连接管理：三次握手、四次挥手、TIME_WAIT&quot;">​</a></h1><blockquote><p>面试第一高频。但这题真正的分水岭不在&quot;背出三次&quot;，而在**&quot;为什么不是两次&quot;<strong>和</strong>&quot;TIME_WAIT 为什么必须等 2MSL&quot;**。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>TCP 是<strong>双向</strong>的可靠通道。建立时要<strong>双方各自确认&quot;我能发、你能收&quot;</strong>，断开时要<strong>双方各自确认&quot;我没数据了&quot;</strong>——所以各要一轮半。</p><h2 id="生活类比-打电话" tabindex="-1">生活类比：打电话 <a class="header-anchor" href="#生活类比-打电话" aria-label="Permalink to &quot;生活类比：打电话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>TCP</th><th>打电话</th></tr></thead><tbody><tr><td>三次握手</td><td>&quot;喂，你能听见吗？&quot; → &quot;能听见，你能听见我吗？&quot; → &quot;能听见&quot;</td></tr><tr><td>四次挥手</td><td>&quot;我说完了&quot; → &quot;好，我知道了&quot; → （对方也说完）&quot;我也说完了&quot; → &quot;好，挂吧&quot;</td></tr><tr><td>TIME_WAIT</td><td>挂电话后等一会再走，万一对方还有话没说完</td></tr><tr><td>半连接队列</td><td>电话响了但还没接起来的那些</td></tr><tr><td>SYN Flood</td><td>有人一直打骚扰电话，让你接线员忙不过来</td></tr></tbody></table><p><strong>为什么不能只问一句&quot;能听见吗&quot;？</strong> 因为你说&quot;能听见吗&quot;只证明<strong>你的话筒</strong>好使，不能证明<strong>你的听筒</strong>好使。必须对方回一句、你再确认一句，双方才都确认了&quot;我发得出、我收得到&quot;。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><p>先看全景：建立要 3 个报文段，断开要 4 个。</p>',9),s("figure",{class:"fig"},[s("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),s("svg",{viewBox:"0 0 680 480",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"TCP 三次握手与四次挥手时序图"},[s("defs",null,[s("marker",{id:"arw-tcp",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[s("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),s("rect",{class:"f-box",x:"50",y:"14",width:"160",height:"40",rx:"8"}),s("text",{class:"f-title",x:"130",y:"40","text-anchor":"middle"},"客户端"),s("rect",{class:"f-box",x:"440",y:"14",width:"160",height:"40",rx:"8"}),s("text",{class:"f-title",x:"520",y:"40","text-anchor":"middle"},"服务器"),s("path",{class:"f-line f-dash",d:"M130 54 V452"}),s("path",{class:"f-line f-dash",d:"M520 54 V452"}),s("text",{class:"f-label",x:"650",y:"62","text-anchor":"middle"},"时间"),s("path",{class:"f-line",d:"M650 72 V420","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-label",x:"325",y:"84","text-anchor":"middle"},"三次握手：双方各自确认「我发得出、你收得到」"),s("path",{class:"f-line",d:"M130 108 H520","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"140",y:"100"},"SYN, seq=x"),s("path",{class:"f-line",d:"M520 150 H130","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"510",y:"142","text-anchor":"end"},"SYN+ACK, seq=y, ack=x+1"),s("path",{class:"f-line",d:"M130 192 H520","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"140",y:"184"},"ACK, ack=y+1"),s("text",{class:"f-label",x:"325",y:"218","text-anchor":"middle"},"连接建立，双方进入 ESTABLISHED"),s("path",{class:"f-line f-dash",d:"M60 238 H600"}),s("text",{class:"f-label",x:"325",y:"262","text-anchor":"middle"},"四次挥手：两个方向各自关闭"),s("path",{class:"f-line",d:"M130 288 H520","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"140",y:"280"},"FIN, seq=u"),s("path",{class:"f-line",d:"M520 326 H130","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"510",y:"318","text-anchor":"end"},"ACK, ack=u+1"),s("path",{class:"f-line f-dash",d:"M520 362 H130","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"510",y:"354","text-anchor":"end"},"… 继续发剩余数据 …"),s("path",{class:"f-line",d:"M520 398 H130","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"510",y:"390","text-anchor":"end"},"FIN, seq=w"),s("path",{class:"f-line",d:"M130 436 H520","marker-end":"url(#arw-tcp)"}),s("text",{class:"f-mono",x:"140",y:"428"},"ACK, ack=w+1"),s("text",{class:"f-label",x:"130",y:"468"},"客户端进入 TIME_WAIT，等 2MSL 才真正关闭")]),s("figcaption",{class:"fig-cap"},"第三次握手不是客套：它让服务器确认「客户端真的收到了我的 SYN」，否则一个迷路的旧 SYN 就能骗走一份连接资源。四次挥手多出来的一次，是因为 ACK 和 FIN 不能合并——服务器可能还有数据没发完。")],-1),t(`<h3 id="一、三次握手-建立连接" tabindex="-1">一、三次握手（建立连接） <a class="header-anchor" href="#一、三次握手-建立连接" aria-label="Permalink to &quot;一、三次握手（建立连接）&quot;">​</a></h3><p><strong>三次各自确认了什么</strong>（这是回答&quot;为什么三次&quot;的核心）：</p><table tabindex="0"><thead><tr><th>次数</th><th>谁确认了什么</th></tr></thead><tbody><tr><td>第 1 次后</td><td>服务器确认：<strong>客户端发送能力正常</strong>、<strong>自己接收能力正常</strong></td></tr><tr><td>第 2 次后</td><td>客户端确认：<strong>自己发送正常</strong>、<strong>自己接收正常</strong>、<strong>服务器收发都正常</strong></td></tr><tr><td>第 3 次后</td><td>服务器确认：<strong>自己发送正常</strong>、<strong>客户端接收正常</strong></td></tr></tbody></table><p><strong>只有第 3 次完成后，双方才都确认了&quot;四个方向全通&quot;</strong>。</p><h3 id="二、为什么不是两次-最高频追问" tabindex="-1">二、为什么不是两次（最高频追问） <a class="header-anchor" href="#二、为什么不是两次-最高频追问" aria-label="Permalink to &quot;二、为什么不是两次（最高频追问）&quot;">​</a></h3><p>假设只有两次握手（客户端发 SYN，服务器回 SYN+ACK 就认为连接建立）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：一个&quot;迷路的旧 SYN&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 客户端很久以前发了一个 SYN（seq=100），在网络里堵了很久</span></span>
<span class="line"><span>② 客户端等不到，超时重发了一个新的 SYN（seq=200），完成握手，传完数据，正常关闭</span></span>
<span class="line"><span>③ 此时，那个迷路的旧 SYN（seq=100）终于到达服务器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两次握手的情况：</span></span>
<span class="line"><span>   服务器收到旧 SYN &gt; 立刻回 SYN+ACK &gt; 并认为&quot;连接已建立&quot;，分配资源、进入 ESTABLISHED</span></span>
<span class="line"><span>   但客户端根本没想连（它认为这是垃圾包，回一个 RST 或者直接忽略）</span></span>
<span class="line"><span>   &gt; 服务器白建了一个连接，占着资源干等，直到超时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三次握手的情况：</span></span>
<span class="line"><span>   服务器回 SYN+ACK 后进入 SYN_RCVD（半开状态），不分配完整资源</span></span>
<span class="line"><span>   客户端收到这个莫名其妙的 SYN+ACK &gt; 回 RST</span></span>
<span class="line"><span>   服务器收到 RST &gt; 释放，什么损失都没有</span></span></code></pre></div><p><strong>一句话总结</strong>：<strong>三次握手的第三次，是让服务器&quot;确认客户端真的收到了我的 SYN&quot;，从而避免被历史连接骗走资源</strong>。</p><p>（另一种说法：两次握手无法防止&quot;已失效的连接请求突然又传到服务端&quot;，本质是同一件事。）</p><h3 id="三、四次挥手-断开连接" tabindex="-1">三、四次挥手（断开连接） <a class="header-anchor" href="#三、四次挥手-断开连接" aria-label="Permalink to &quot;三、四次挥手（断开连接）&quot;">​</a></h3><p>TCP 是<strong>全双工</strong>的，两个方向要<strong>各自关闭</strong>：</p><p>客户端发完 FIN 后进入 <code>FIN_WAIT_1</code>，收到服务器的 ACK 就转 <code>FIN_WAIT_2</code>——此时「客户端 → 服务器」这个方向已经关了，但反方向还开着。服务器那边进入 <code>CLOSE_WAIT</code>，把剩余数据发完，再补一个 FIN；客户端回最后一个 ACK，进入 <code>TIME_WAIT</code>。</p><p>注意 <strong><code>FIN_WAIT_2</code> 和 <code>CLOSE_WAIT</code> 是同一时刻、分处两端</strong>的两个状态：一个在等对方的 FIN，一个在等自己的程序调 <code>close()</code>。</p><p><strong>为什么是四次不是三次</strong>：因为服务器收到 FIN 后，<strong>可能还有数据没发完</strong>。所以 ACK 和 FIN 不能合并，必须分开发。</p><p><strong>例外</strong>：如果服务器收到 FIN 时确实没数据要发了，ACK 和 FIN 可以合并成一次（延迟确认机制），变成&quot;三次挥手&quot;。这是常见的追问点。</p><h3 id="四、time-wait-为什么必须等-2msl" tabindex="-1">四、TIME_WAIT：为什么必须等 2MSL <a class="header-anchor" href="#四、time-wait-为什么必须等-2msl" aria-label="Permalink to &quot;四、TIME_WAIT：为什么必须等 2MSL&quot;">​</a></h3><p>主动关闭的一方（这里是客户端）在发完最后一个 ACK 后，进入 <code>TIME_WAIT</code>，等 <strong>2MSL</strong>（MSL = 报文最大生存时间，Linux 上通常 60 秒，所以等 120 秒）才真正关闭。</p><p><strong>两个理由（必须都说）</strong>：</p><p><strong>理由 1：保证最后一个 ACK 能到达对方</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果最后那个 ACK 丢了：</span></span>
<span class="line"><span>   服务器会重发 FIN（因为它没收到 ACK）</span></span>
<span class="line"><span>   此时客户端如果已经关闭 &gt; 收到 FIN 会回 RST</span></span>
<span class="line"><span>   服务器收到 RST 会认为&quot;异常终止&quot;，而不是&quot;正常关闭&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果客户端还在 TIME_WAIT：</span></span>
<span class="line"><span>   收到重发的 FIN &gt; 再回一次 ACK &gt; 服务器正常关闭</span></span></code></pre></div><p><strong>理由 2：让旧连接的残留报文在网络中消亡</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果没有 TIME_WAIT，客户端立刻用相同的四元组建新连接：</span></span>
<span class="line"><span>   旧连接的延迟报文（比如一个迟到的数据段）到达服务器</span></span>
<span class="line"><span>   服务器以为是新连接的数据 &gt; 数据错乱</span></span>
<span class="line"><span></span></span>
<span class="line"><span>等 2MSL，足以让这个方向上所有报文都过期消失</span></span>
<span class="line"><span>（一来一回的最长时间 = 2 × MSL）</span></span></code></pre></div><p><strong>为什么是 2MSL 而不是 1MSL</strong>：因为要覆盖&quot;我的 ACK 到对方&quot;+&quot;对方的 FIN 到我&quot;这一个完整往返。</p><h3 id="五、close-wait-过多-代码-bug" tabindex="-1">五、CLOSE_WAIT 过多 = 代码 bug <a class="header-anchor" href="#五、close-wait-过多-代码-bug" aria-label="Permalink to &quot;五、CLOSE_WAIT 过多 = 代码 bug&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLOSE_WAIT 状态：被动关闭方收到了 FIN，回了 ACK，但自己的程序还没调 close()</span></span></code></pre></div><p><strong>大量 CLOSE_WAIT 意味着</strong>：你的程序收到了对方的关闭请求，但<strong>没有正确关闭 socket</strong>（忘了 <code>close()</code>、或者连接池没释放、或者异常路径没走到 finally）。</p><p><strong>这不是网络问题，是代码问题</strong>。而大量 TIME_WAIT 通常是正常的（主动关闭方多），可以通过 <code>SO_REUSEADDR</code>、调整内核参数缓解。</p><table tabindex="0"><thead><tr><th>状态</th><th>谁的问题</th><th>怎么办</th></tr></thead><tbody><tr><td>大量 TIME_WAIT</td><td>主动关闭方，通常正常</td><td>调 <code>tcp_tw_reuse</code>、用长连接</td></tr><tr><td>大量 CLOSE_WAIT</td><td>被动关闭方，<strong>代码 bug</strong></td><td>检查 close 调用、连接池泄漏</td></tr></tbody></table><h3 id="六、syn-队列与-syn-flood" tabindex="-1">六、SYN 队列与 SYN Flood <a class="header-anchor" href="#六、syn-队列与-syn-flood" aria-label="Permalink to &quot;六、SYN 队列与 SYN Flood&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务器维护两个队列：</span></span>
<span class="line"><span>  半连接队列（SYN queue）：收到 SYN，回了 SYN+ACK，等对方 ACK</span></span>
<span class="line"><span>  全连接队列（accept queue）：握手完成，等应用调 accept()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SYN Flood 攻击：</span></span>
<span class="line"><span>  攻击者发大量 SYN，但**不回最后一个 ACK**</span></span>
<span class="line"><span>  &gt; 半连接队列被塞满</span></span>
<span class="line"><span>  &gt; 正常用户的 SYN 被丢弃</span></span>
<span class="line"><span>  &gt; 服务不可用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>防御：</span></span>
<span class="line"><span>  ① SYN Cookie：不回 SYN+ACK 时不分配资源，把状态编码进 seq 号</span></span>
<span class="line"><span>  ② 增大队列、缩短超时</span></span>
<span class="line"><span>  ③ 限流 / 防火墙</span></span></code></pre></div><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果两次握手" tabindex="-1">反事实 1：如果两次握手 <a class="header-anchor" href="#反事实-1-如果两次握手" aria-label="Permalink to &quot;反事实 1：如果两次握手&quot;">​</a></h3><p>服务器会被历史 SYN 骗走资源（上面详述）。更严重的是：<strong>服务器无法区分&quot;客户端想连&quot;和&quot;客户端早就不要了&quot;</strong>，在 SYN Flood 场景下更容易被打垮。</p><h3 id="反事实-2-如果没有-time-wait" tabindex="-1">反事实 2：如果没有 TIME_WAIT <a class="header-anchor" href="#反事实-2-如果没有-time-wait" aria-label="Permalink to &quot;反事实 2：如果没有 TIME_WAIT&quot;">​</a></h3><ol><li>最后一个 ACK 丢了 &gt; 服务器一直重发 FIN，客户端已关闭回 RST &gt; 服务器报异常关闭，日志里全是错误。</li><li>旧连接的延迟报文污染新连接 &gt; 数据错乱，且极难排查（偶发、无法复现）。</li></ol><h3 id="反事实-3-如果-tcp-是半双工-只能一方说" tabindex="-1">反事实 3：如果 TCP 是半双工（只能一方说） <a class="header-anchor" href="#反事实-3-如果-tcp-是半双工-只能一方说" aria-label="Permalink to &quot;反事实 3：如果 TCP 是半双工（只能一方说）&quot;">​</a></h3><p>那断开只要两次挥手就够了。但 TCP 是全双工，两个方向独立关闭，所以需要四次。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：三次握手的过程？为什么不是两次？</strong></p><blockquote><p>先讲过程（SYN / SYN+ACK / ACK，带序号），再讲&quot;四个方向&quot;的确认逻辑，最后用&quot;历史 SYN 骗资源&quot;说明为什么两次不行。 <strong>加分</strong>：提到&quot;第三次握手可以携带数据&quot;（前两次不行，因为还没建立，带数据容易被利用放大攻击）。</p></blockquote><p><strong>Q：四次挥手的过程？为什么不是三次？</strong></p><blockquote><p>因为全双工，服务器收到 FIN 时可能还有数据要发，所以 ACK 和 FIN 分开。 <strong>加分</strong>：如果服务器确实没数据了，ACK+FIN 可以合并，实际就是三次。</p></blockquote><p><strong>Q：TIME_WAIT 为什么要等 2MSL？</strong></p><blockquote><p>两个理由：① 保证最后的 ACK 能到达（丢了还能重发）；② 让旧连接的残留报文消亡，避免污染新连接。2MSL 覆盖一个完整往返。</p></blockquote><p><strong>Q：服务器出现大量 CLOSE_WAIT 怎么办？</strong></p><blockquote><p>这是<strong>代码没关闭连接</strong>的信号（不是网络问题）。检查：连接池是否泄漏、异常分支是否漏了 close、是否用了 try-with-resources / defer。</p></blockquote><p><strong>Q：SYN Flood 怎么防？</strong></p><blockquote><p>SYN Cookie（不预分配资源，把状态编进 seq）、增大半连接队列、缩短 SYN 超时、上游限流。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三次握手过程？</span></span>
<span class="line"><span>  &gt; 为什么是三次不是两次？（历史 SYN 骗资源）</span></span>
<span class="line"><span>    &gt; 第三次能带数据吗？（能，前两次不能）</span></span>
<span class="line"><span>      &gt; 序号为什么是随机的？（防止历史报文被误认为当前连接 / 安全）</span></span>
<span class="line"><span>        &gt; 那 ISN 怎么生成的？（时钟 + 四元组哈希，Linux 做法）</span></span>
<span class="line"><span>          &gt; 断开为什么是四次？（全双工，两个方向独立关）</span></span>
<span class="line"><span>            &gt; TIME_WAIT 为什么 2MSL？（ACK 可达 + 残留报文消亡）</span></span>
<span class="line"><span>              &gt; 大量 TIME_WAIT 怎么办？（SO_REUSEADDR / 长连接 / 调参）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：TCP 头里的端口和序号，是握手的载体</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/03">TCP 可靠传输与拥塞控制</a>：握手协商的 MSS 和窗口，决定后续传输效率</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/04">HTTP / HTTPS 与缓存</a>：HTTP/1.1 的 <code>Connection: keep-alive</code> 就是为了避免反复握手；HTTPS 在 TCP 之上再加一轮 TLS 握手</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：<code>accept()</code> 从全连接队列取连接，队列满了新连接会被丢弃或拒绝</li><li><strong>&gt; 影响</strong> 工程实践：连接池、长连接、<code>keep-alive</code> 的存在理由就是&quot;握手太贵&quot;</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：第三次握手可以携带数据吗？前两次呢？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>第三次可以，前两次不行。</strong></p><ul><li>第一次（SYN）不能带数据：此时服务器还没分配资源，如果允许带数据，攻击者可以用一个 SYN 塞满数据，放大攻击（SYN Flood 的变种）。</li><li>第二次（SYN+ACK）也不能：客户端此时还没确认连接。</li><li>第三次（ACK）可以：客户端已经确认了服务器的收发能力，服务器收到这个 ACK 后连接就建立了，数据可以直接跟上。</li></ul><p>实际上很多实现会把第一个数据段和第三次握手合并（TCP Fast Open 更进一步，在 SYN 里就带数据，用 Cookie 验证）。</p></details><p><strong>Q2：为什么序号（ISN）要随机，不能从 0 或 1 开始？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>两个原因：</p><ol><li><strong>防止历史报文被误接收</strong>。如果每次都从 1 开始，一个上一次连接的延迟报文（seq=500）到达时，可能正好落在新连接的接收窗口内，被当成有效数据。</li><li><strong>安全</strong>。可预测的 ISN 让攻击者能伪造 TCP 包（TCP 序列号预测攻击），注入数据或劫持连接。</li></ol><p>Linux 的 ISN 生成方式大致是：<code>ISN = 时钟（每 4 微秒加 1）+ 四元组哈希</code>。既难预测，又保证同一四元组短时间内不会重复。</p></details><p><strong>Q3：大量 TIME_WAIT 是坏事吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不一定是坏事</strong>。TIME_WAIT 出现在<strong>主动关闭方</strong>，说明你的服务在主动关连接——这是正常的（比如 HTTP 短连接、服务端主动踢掉空闲连接）。</p><p>问题在于：</p><ul><li>每个 TIME_WAIT 占用一个四元组，<strong>端口有限</strong>（约 6 万个可用端口），大量短连接会导致端口耗尽，无法建新连接。</li><li>内存占用（每个 TIME_WAIT 一个小结构）。</li></ul><p>处理方式（按推荐顺序）：</p><ol><li><strong>用长连接</strong>（HTTP keep-alive、连接池）——根治。</li><li><code>net.ipv4.tcp_tw_reuse = 1</code>——允许复用 TIME_WAIT 的端口建新连接（安全，因为序号已经随机化）。</li><li><strong>不要</strong>用 <code>tcp_tw_recycle</code>——它在 NAT 环境下会导致连接失败，已被移除。</li></ol><p>对比：<strong>CLOSE_WAIT 才是真问题</strong>，那是代码没关连接。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;打电话&quot;类比会让人以为握手是&quot;聊天&quot;</strong>。实际每个报文都有严格格式和序号，且可能丢失重传。</li><li><strong>&quot;三次握手建立连接&quot;不严谨</strong>。TCP 没有&quot;连接&quot;这个实体，所谓连接只是<strong>双方各自维护的一份状态</strong>（四元组 + 序号 + 窗口）。断网时双方状态还在，所以会&quot;假连接&quot;。</li><li><strong>TIME_WAIT 出现在主动关闭方，不是固定出现在客户端</strong>。谁先 <code>close()</code> 谁进 TIME_WAIT。HTTP 里通常是服务端主动关（如果设了 <code>Connection: close</code>），所以服务端 TIME_WAIT 多。</li><li><strong>半关闭（half-close）</strong>：调用 <code>shutdown(SHUT_WR)</code> 只关写方向，还能继续读。这就是四次挥手能存在的基础。</li><li><strong>RST 不是&quot;正常关闭&quot;</strong>。收到 RST 意味着对方不认这个连接（端口没监听、进程崩了、或者被防火墙拦），会立刻释放，不走四次挥手。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出三次握手的时序图，标出 seq/ack 的具体变化</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说清&quot;三次各自确认了哪几个方向&quot;，并用此推出&quot;为什么两次不行&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能用&quot;历史 SYN 骗资源&quot;完整讲一个两次握手会出事的场景</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能画出四次挥手时序图，并解释&quot;为什么 ACK 和 FIN 不能合并&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出 TIME_WAIT 等 2MSL 的<strong>两个</strong>理由，并解释为什么是 2 而不是 1</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能区分 TIME_WAIT 和 CLOSE_WAIT 的成因，并说出各自的处理方式</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能解释 SYN Flood 的原理和 SYN Cookie 的防御思路</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,63)])])}const q=n(l,[["render",p]]);export{g as __pageData,q as default};
